import { Request, Response } from 'express';
import { PlaceOrderUseCase } from '../application/place-order';
import { TransitionOrderUseCase } from '../application/transition-order';
import { CancelOrderUseCase } from '../application/cancel-order';
import { ListOrdersUseCase } from '../application/list-orders';
import { OrderState } from '../domain/types';

export class OrderController {
  constructor(
    private placeOrderUseCase: PlaceOrderUseCase,
    private transitionOrderUseCase: TransitionOrderUseCase,
    private cancelOrderUseCase: CancelOrderUseCase,
    private listOrdersUseCase: ListOrdersUseCase
  ) {}

  placeOrder(req: Request, res: Response): void {
    try {
      const result = this.placeOrderUseCase.execute(req.body);
      res.status(201).json(result);
    } catch (error) {
      this.handleError(error, res);
    }
  }

  transitionOrder(req: Request, res: Response): void {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      const { state } = req.body;
      const result = this.transitionOrderUseCase.execute(orderId, state as OrderState);
      res.status(200).json(result);
    } catch (error) {
      this.handleError(error, res);
    }
  }

  cancelOrder(req: Request, res: Response): void {
    try {
      const orderId = Array.isArray(req.params.orderId) ? req.params.orderId[0] : req.params.orderId;
      const result = this.cancelOrderUseCase.execute(orderId);
      res.status(200).json(result);
    } catch (error) {
      this.handleError(error, res);
    }
  }

  listByState(req: Request, res: Response): void {
    try {
      const state = Array.isArray(req.params.state) ? req.params.state[0] : req.params.state;
      const result = this.listOrdersUseCase.executeByState(state as OrderState);
      res.status(200).json(result);
    } catch (error) {
      this.handleError(error, res);
    }
  }

  listAll(req: Request, res: Response): void {
    try {
      const result = this.listOrdersUseCase.executeAll();
      res.status(200).json(result);
    } catch (error) {
      this.handleError(error, res);
    }
  }

  private handleError(error: unknown, res: Response): void {
    if (error instanceof Error) {
      if (error.name === 'InsufficientStockError' || error.name === 'ProductNotFoundError') {
        res.status(400).json({ error: error.message });
      } else if (error.name === 'OrderNotFoundError') {
        res.status(404).json({ error: error.message });
      } else if (error.name === 'InvalidStateTransitionError') {
        res.status(400).json({ error: error.message });
      } else {
        res.status(500).json({ error: error.message });
      }
    } else {
      res.status(500).json({ error: 'Internal server error' });
    }
  }
}

