import express, { Express } from 'express';
import { OrderController } from './order-controller';
import { ProductController } from './product-controller';
import { PlaceOrderUseCase } from '../application/place-order';
import { TransitionOrderUseCase } from '../application/transition-order';
import { CancelOrderUseCase } from '../application/cancel-order';
import { ListOrdersUseCase } from '../application/list-orders';
import { ListProductsUseCase } from '../application/list-products';
import { InMemoryProductRepository } from './in-memory-product-repository';
import { InMemoryOrderRepository } from './in-memory-order-repository';
import { OrderDomainService } from '../domain/order-service';
import { Product } from '../domain/types';

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const initialProducts: Product[] = [
    { id: 'PROD-1', name: 'Laptop', price: 999.99, stock: 10 },
    { id: 'PROD-2', name: 'Mouse', price: 29.99, stock: 50 },
    { id: 'PROD-3', name: 'Keyboard', price: 79.99, stock: 30 },
  ];

  const productRepo = new InMemoryProductRepository(initialProducts);
  const orderRepo = new InMemoryOrderRepository();
  const orderService = new OrderDomainService();

  const placeOrderUseCase = new PlaceOrderUseCase(productRepo, orderRepo, orderService);
  const transitionOrderUseCase = new TransitionOrderUseCase(orderRepo, orderService);
  const cancelOrderUseCase = new CancelOrderUseCase(orderRepo, productRepo, orderService);
  const listOrdersUseCase = new ListOrdersUseCase(orderRepo);
  const listProductsUseCase = new ListProductsUseCase(productRepo);

  const orderController = new OrderController(
    placeOrderUseCase,
    transitionOrderUseCase,
    cancelOrderUseCase,
    listOrdersUseCase
  );

  const productController = new ProductController(listProductsUseCase);

  app.post('/orders', (req, res) => orderController.placeOrder(req, res));
  app.get('/orders', (req, res) => orderController.listAll(req, res));
  app.get('/orders/state/:state', (req, res) => orderController.listByState(req, res));
  app.patch('/orders/:orderId/transition', (req, res) => orderController.transitionOrder(req, res));
  app.delete('/orders/:orderId', (req, res) => orderController.cancelOrder(req, res));

  app.get('/products', (req, res) => productController.listAll(req, res));

  return app;
}

export function startServer(port: number = 3000): void {
  const app = createApp();
  app.listen(port, () => {
    console.log(`Order fulfillment server running on port ${port}`);
  });
}

