import { TaskAlreadyDoneError } from '../errors/TaskAlreadyDoneError';
import { ValidationError } from '../errors/ValidationError';
import { DueDate } from '../value-objects/DueDate';
import { TaskStatus } from '../value-objects/TaskStatus';
import { User } from './User';

export interface NewTask {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: DueDate;
  status?: TaskStatus;
}

export class Task {
  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: DueDate | undefined,
    private currentStatus: TaskStatus,
    private currentAssigneeId: string | undefined,
  ) {}

  static create(input: NewTask): Task {
    const title = input.title.trim();
    if (title.length === 0) {
      throw new ValidationError('Task title must not be empty');
    }
    return new Task(
      input.id,
      input.projectId,
      title,
      input.description,
      input.dueDate,
      input.status ?? 'todo',
      undefined,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | undefined {
    return this.currentAssigneeId;
  }

  /** Taking a `User` rather than an id means only existing users can be assigned. */
  assignTo(user: User): void {
    this.currentAssigneeId = user.id;
  }

  markDone(): void {
    if (this.currentStatus === 'done') {
      throw new TaskAlreadyDoneError(this.id);
    }
    this.currentStatus = 'done';
  }
}

