import { ConflictError, ValidationError } from "./errors";

export const TASK_STATUSES = ["todo", "in_progress", "done"] as const;

export type TaskStatus = (typeof TASK_STATUSES)[number];

export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
}

export interface TaskProps {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate: Date | null;
  readonly status: TaskStatus;
  readonly assigneeId: string | null;
  readonly createdAt: Date;
}

export interface TaskJSON {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: string | null;
  status: TaskStatus;
  assigneeId: string | null;
  createdAt: string;
}

export class Task {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate: Date | null;
  readonly createdAt: Date;
  private _status: TaskStatus;
  private _assigneeId: string | null;

  private constructor(props: TaskProps) {
    this.id = props.id;
    this.projectId = props.projectId;
    this.title = props.title;
    this.description = props.description;
    this.dueDate = props.dueDate;
    this.createdAt = props.createdAt;
    this._status = props.status;
    this._assigneeId = props.assigneeId;
  }

  static create(props: TaskProps): Task {
    const title = props.title.trim();
    if (title.length === 0) {
      throw new ValidationError("Task title must not be empty");
    }
    if (!isTaskStatus(props.status)) {
      throw new ValidationError(`Task status must be one of: ${TASK_STATUSES.join(", ")}`);
    }
    if (props.dueDate !== null && Number.isNaN(props.dueDate.getTime())) {
      throw new ValidationError("Task due date is not a valid date");
    }
    return new Task({ ...props, title });
  }

  get status(): TaskStatus {
    return this._status;
  }

  get assigneeId(): string | null {
    return this._assigneeId;
  }

  assignTo(userId: string): void {
    this._assigneeId = userId;
  }

  markDone(): void {
    if (this._status === "done") {
      throw new ConflictError(`Task '${this.id}' is already done`);
    }
    this._status = "done";
  }

  toJSON(): TaskJSON {
    return {
      id: this.id,
      projectId: this.projectId,
      title: this.title,
      description: this.description,
      dueDate: this.dueDate ? this.dueDate.toISOString() : null,
      status: this._status,
      assigneeId: this._assigneeId,
      createdAt: this.createdAt.toISOString(),
    };
  }
}

