import { Request, Response, Router } from "express";
import { DomainError } from "../domain/domain-error";
import { FulfilmentState } from "../domain/order-state";
import { PlaceOrderCommand } from "../application/order-dto";
import { AdvanceOrderUseCase } from "../application/advance-order-use-case";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { GetOrderUseCase } from "../application/get-order-use-case";
import { ListOrdersByStateUseCase } from "../application/list-orders-by-state-use-case";
import { PlaceOrderUseCase } from "../application/place-order-use-case";

const ADVANCE_ACTIONS: ReadonlyArray<readonly [string, FulfilmentState]> = [
  ["pay", "paid"],
  ["pack", "packed"],
  ["ship", "shipped"],
  ["deliver", "delivered"],
];

function parsePlaceOrder(body: unknown): PlaceOrderCommand {
  const lines = (body as { lines?: unknown } | undefined)?.lines;
  if (!Array.isArray(lines)) {
    throw new DomainError("validation", "Body must contain a 'lines' array");
  }
  return {
    lines: lines.map((raw: unknown) => {
      const line = (raw ?? {}) as { productId?: unknown; quantity?: unknown };
      if (typeof line.productId !== "string" || typeof line.quantity !== "number") {
        throw new DomainError("validation", "Each line needs a string productId and numeric quantity");
      }
      return { productId: line.productId, quantity: line.quantity };
    }),
  };
}

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly getOrder: GetOrderUseCase,
    private readonly advanceOrder: AdvanceOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
    private readonly listOrders: ListOrdersByStateUseCase,
  ) {}

  router(): Router {
    const router = Router();
    router.post("/", async (req: Request, res: Response) => {
      res.status(201).json(await this.placeOrder.execute(parsePlaceOrder(req.body)));
    });
    router.get("/", async (req: Request, res: Response) => {
      const state = req.query.state;
      if (typeof state !== "string") {
        throw new DomainError("validation", "Query parameter 'state' is required");
      }
      res.json(await this.listOrders.execute(state));
    });
    router.get("/:id", async (req: Request, res: Response) => {
      res.json(await this.getOrder.execute(String(req.params.id)));
    });
    router.post("/:id/cancel", async (req: Request, res: Response) => {
      res.json(await this.cancelOrder.execute(String(req.params.id)));
    });
    for (const [action, target] of ADVANCE_ACTIONS) {
      router.post(`/:id/${action}`, async (req: Request, res: Response) => {
        res.json(await this.advanceOrder.execute(String(req.params.id), target));
      });
    }
    return router;
  }
}

