import express, { Express } from "express";
import { AdvanceOrderUseCase } from "../application/AdvanceOrderUseCase";
import { CancelOrderUseCase } from "../application/CancelOrderUseCase";
import { GetStockLevelsUseCase } from "../application/GetStockLevelsUseCase";
import { ListOrdersByStatusUseCase } from "../application/ListOrdersByStatusUseCase";
import { PlaceOrderUseCase } from "../application/PlaceOrderUseCase";
import { Product } from "../domain/Product";
import { StockReservationService } from "../domain/StockReservationService";
import { InMemoryOrderRepository } from "./InMemoryOrderRepository";
import { InMemoryProductRepository } from "./InMemoryProductRepository";
import { OrderController } from "./OrderController";
import { SequentialIdGenerator } from "./SequentialIdGenerator";
import { StockController } from "./StockController";
import { errorHandler } from "./errorHandler";

type AsyncHandler = (req: express.Request, res: express.Response) => Promise<void>;

function wrap(handler: AsyncHandler): express.RequestHandler {
  return (req, res, next) => {
    handler(req, res).catch(next);
  };
}

export function createApp(catalogue: readonly Product[]): Express {
  const products = new InMemoryProductRepository(catalogue);
  const orders = new InMemoryOrderRepository();
  const stock = new StockReservationService(products);

  const orderController = new OrderController(
    new PlaceOrderUseCase(orders, stock, new SequentialIdGenerator()),
    new AdvanceOrderUseCase(orders),
    new CancelOrderUseCase(orders, stock),
    new ListOrdersByStatusUseCase(orders),
  );
  const stockController = new StockController(new GetStockLevelsUseCase(products));

  const app = express();
  app.use(express.json());
  app.post("/orders", wrap(orderController.place));
  app.get("/orders", wrap(orderController.list));
  app.post("/orders/:id/advance", wrap(orderController.advance));
  app.post("/orders/:id/cancel", wrap(orderController.cancel));
  app.get("/stock", wrap(stockController.list));
  app.use(errorHandler);
  return app;
}

