import { AssignTaskUseCase } from '../application/AssignTaskUseCase';
import { CreateProjectUseCase } from '../application/CreateProjectUseCase';
import { CreateTaskUseCase } from '../application/CreateTaskUseCase';
import { CreateUserUseCase } from '../application/CreateUserUseCase';
import { ListProjectTasksUseCase } from '../application/ListProjectTasksUseCase';
import { MarkTaskDoneUseCase } from '../application/MarkTaskDoneUseCase';
import { InMemoryProjectRepository } from './InMemoryProjectRepository';
import { InMemoryTaskRepository } from './InMemoryTaskRepository';
import { InMemoryUserRepository } from './InMemoryUserRepository';
import { UuidGenerator } from './UuidGenerator';

export interface UseCases {
  createUser: CreateUserUseCase;
  createProject: CreateProjectUseCase;
  createTask: CreateTaskUseCase;
  listTasks: ListProjectTasksUseCase;
  assignTask: AssignTaskUseCase;
  markTaskDone: MarkTaskDoneUseCase;
}

export function buildUseCases(): UseCases {
  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();
  const ids = new UuidGenerator();
  return {
    createUser: new CreateUserUseCase(users, ids),
    createProject: new CreateProjectUseCase(projects, ids),
    createTask: new CreateTaskUseCase(projects, tasks, users, ids),
    listTasks: new ListProjectTasksUseCase(projects, tasks),
    assignTask: new AssignTaskUseCase(tasks, users),
    markTaskDone: new MarkTaskDoneUseCase(tasks),
  };
}

