import { Request, Response, Router } from "express";
import { CreateProjectUseCase } from "../application/CreateProjectUseCase";
import { CreateTaskUseCase } from "../application/CreateTaskUseCase";
import { CreateUserUseCase } from "../application/CreateUserUseCase";
import { ListProjectTasksUseCase } from "../application/ListProjectTasksUseCase";
import { MarkTaskDoneUseCase } from "../application/MarkTaskDoneUseCase";
import { CreateTaskInput } from "../application/TaskDtos";
import { DomainError } from "../domain/DomainError";
import { isTaskStatus } from "../domain/TaskStatus";

interface TaskApiUseCases {
  createUser: CreateUserUseCase;
  createProject: CreateProjectUseCase;
  createTask: CreateTaskUseCase;
  listTasks: ListProjectTasksUseCase;
  markDone: MarkTaskDoneUseCase;
}

export class TaskController {
  public constructor(private readonly useCases: TaskApiUseCases) {}

  public router(): Router {
    const router = Router();
    router.post("/users", this.handle((req, res) => {
      const user = this.useCases.createUser.execute(this.requiredString(req.body?.name, "name"));
      res.status(201).json(user);
    }));
    router.post("/projects", this.handle((req, res) => {
      const project = this.useCases.createProject.execute(this.requiredString(req.body?.name, "name"));
      res.status(201).json(project);
    }));
    router.post("/projects/:projectId/tasks", this.handle((req, res) => {
      const input = this.taskInput(this.pathParam(req.params.projectId, "projectId"), req.body);
      res.status(201).json(this.useCases.createTask.execute(input));
    }));
    router.get("/projects/:projectId/tasks", this.handle((req, res) => {
      const status = this.optionalStatus(req.query.status);
      const assigneeId = this.optionalQuery(req.query.assigneeId, "assigneeId");
      res.json(this.useCases.listTasks.execute(this.pathParam(req.params.projectId, "projectId"), status, assigneeId));
    }));
    router.patch("/tasks/:taskId/done", this.handle((req, res) => {
      res.json(this.useCases.markDone.execute(this.pathParam(req.params.taskId, "taskId")));
    }));
    return router;
  }

  private handle(action: (request: Request, response: Response) => void) {
    return (request: Request, response: Response): void => {
      try { action(request, response); } catch (error) {
        const message = error instanceof Error ? error.message : "Unexpected error";
        response.status(error instanceof DomainError ? 400 : 500).json({ error: message });
      }
    };
  }

  private taskInput(projectId: string, body: unknown): CreateTaskInput {
    const value = this.object(body);
    const status = value.status === undefined ? undefined : this.optionalStatus(value.status);
    return {
      projectId,
      title: this.requiredString(value.title, "title"),
      description: this.requiredString(value.description, "description"),
      dueDate: this.optionalString(value.dueDate, "dueDate"),
      assigneeId: this.optionalString(value.assigneeId, "assigneeId"),
      status,
    };
  }

  private object(value: unknown): Record<string, unknown> {
    if (!value || typeof value !== "object" || Array.isArray(value)) throw new DomainError("Request body must be an object");
    return value as Record<string, unknown>;
  }
